function moveEntity(model,dx,dz,radius=.42){if(model===player){const length=Math.hypot(dx,dz);if(length>0)networkDirection={x:dx/length,z:dz/length,...(moveTarget?{stopAt:{x:moveTarget.x,z:moveTarget.z}}:{})};}const p=resolveMove(model.position,dx,dz,environment.obstacles,radius,WORLD_BOUNDS);const moved=Math.hypot(p.x-model.position.x,p.z-model.position.z);model.position.x=p.x;model.position.z=p.z;return moved;}
function groundPing(pos){ringEffect(pos,0xc0c2a1,.25,.65,.45);}
