function slash(pos,a,color,radius,life){const mesh=new T.Mesh(new T.RingGeometry(radius*.965,radius,48,1,-Math.PI/2-.72,1.44),new T.MeshBasicMaterial({color,transparent:true,opacity:.48,depthWrite:false,side:T.DoubleSide,blending:T.AdditiveBlending}));mesh.rotation.set(-Math.PI/2,0,a-.2);mesh.position.copy(pos).add(new T.Vector3(0,.85,0));scene.add(mesh);effects.push({type:'slash',mesh,time:0,life,angle:a});}
function steelImpact(pos){combatEffects.steelImpact(pos);}
function particles(pos,color,count,speed){const values=new Float32Array(count*3),velocity=new Float32Array(count*3);for(let i=0;i<count;i++){velocity[i*3]=(Math.random()-.5)*speed*2;velocity[i*3+1]=Math.random()*speed+1;velocity[i*3+2]=(Math.random()-.5)*speed*2;}const g=new T.BufferGeometry();g.setAttribute('position',new T.BufferAttribute(values,3));const mesh=new T.Points(g,new T.PointsMaterial({color,size:.065,transparent:true,opacity:.9,depthWrite:false,blending:T.AdditiveBlending}));mesh.position.copy(pos);scene.add(mesh);effects.push({type:'particles',mesh,velocity,time:0,life:.75});}
function telegraph(pos,radius,arc=Math.PI*2,a=0){const group=new T.Group();group.position.set(pos.x,.1,pos.z);const mat=new T.MeshBasicMaterial({color:0xe76042,transparent:true,opacity:.15,side:T.DoubleSide,depthWrite:false});const fill=new T.Mesh(new T.CircleGeometry(radius,48,-Math.PI/2-arc/2,arc),mat);fill.rotation.set(-Math.PI/2,0,a);group.add(fill);const edge=new T.Mesh(new T.RingGeometry(radius-.055,radius,48,1,-Math.PI/2-arc/2,arc),new T.MeshBasicMaterial({color:0xf59766,transparent:true,opacity:.48,depthWrite:false,side:T.DoubleSide}));edge.rotation.set(-Math.PI/2,0,a);group.add(edge);scene.add(group);return group;}
function removeObject(object){scene.remove(object);object.traverse(o=>{if(o.geometry&&!o.isSprite)o.geometry.dispose();if(o.material){if(Array.isArray(o.material))o.material.forEach(m=>m.dispose());else o.material.dispose();}});}
function cancelAttack(e,stun=0){if(e.telegraph){removeObject(e.telegraph);e.telegraph=null;}if(stun&&!e.dead){e.phase='recover';e.timer=stun;e.cooldown=.8;}}
function animateRig(rig,t,moving,windup=0,type='warden'){const speed=type==='hound'?13:9;for(let i=0;i<rig.legs.length;i++){const leg=rig.legs[i];const sign=leg.name.includes('L')?-1:1;const back=leg.name.includes('Back')?-1:1;leg.rotation.x=moving?Math.sin(t*speed)*.55*sign*back:Math.sin(t*1.7)*.025;}if(rig.body){rig.body.rotation.z=Math.sin(t*2.1)*.016;rig.body.rotation.x=windup*-.22;rig.body.position.y=(rig.baseY??1.18)+(moving?Math.abs(Math.sin(t*speed))*.035:0);}for(let i=0;i<rig.arms.length;i++){rig.arms[i].rotation.x=windup*-1.3+(moving?Math.sin(t*speed)*(i%2?-.2:.2):Math.sin(t*1.8+i)*.04);}}
function updatePlayer(dt,t){networkDirection={x:0,z:0};if(state.ended){player.rotation.z=T.MathUtils.lerp(player.rotation.z,-1.5,dt*3);return;}let moving=false;const horiz=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0)+joystickValue.x,vert=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0)+joystickValue.y;let dx=.837*horiz+.547*vert,dz=-.547*horiz+.837*vert;
 if(dodgeTime>0){dodgeTime=Math.max(0,dodgeTime-dt);moving=true;player.position.y=Math.sin(Math.max(0,dodgeTime)/.27*Math.PI)*.24;}
 else{player.position.y=0;if(Math.hypot(dx,dz)>.05){moveTarget=null;movePath=[];lockedEnemy=null;life.pending=null;}else if(lockedEnemy&&!lockedEnemy.dead&&attackHeld){const p=lockedEnemy.model.position;angle=Math.atan2(p.x-player.position.x,p.z-player.position.z);if(distance(player.position,p)>abilitiesFor(state).attack.range*.87||!hasLineOfSight(player.position,p,environment.obstacles,.42)){let seek=p;if(!hasLineOfSight(player.position,p,environment.obstacles,.42)){if(!movePath.length)movePath=findPath(player.position,p,environment.obstacles,WORLD_BOUNDS);while(movePath.length&&distance(player.position,movePath[0])<.3)movePath.shift();if(movePath.length)seek=movePath[0];}dx=seek.x-player.position.x;dz=seek.z-player.position.z;}else perform('attack');}else if(moveTarget){dx=moveTarget.x-player.position.x;dz=moveTarget.z-player.position.z;if(Math.hypot(dx,dz)<.1){const next=movePath.shift();moveTarget=next?new T.Vector3(next.x,0,next.z):null;dx=dz=0;}}if(Math.hypot(dx,dz)>.05){const length=Math.hypot(dx,dz);dx/=length;dz/=length;lastMove.set(dx,0,dz);const travel=moveTarget?Math.min(length,classFor(state).speed*dt):classFor(state).speed*dt;moving=moveEntity(player,dx*travel,dz*travel)>.001;if(!attackHeld)angle=Math.atan2(dx,dz);}else if(aimActive){getPointerWorld();angle=Math.atan2(targetWorld.x-player.position.x,targetWorld.z-player.position.z);}if(attackHeld&&!lockedEnemy)perform('attack');}
 network.input={...networkDirection,angle};player.rotation.y=angle;animateRig(heroRig,t,moving);animateHeroAttack(heroRig,dt);if(moving&&t-lastStep>.29){audio.play(footstepCue(),.48);lastStep=t;}selection.position.set(player.position.x,.1,player.position.z);selection.material.opacity=dodgeTime>0?.2:.55;playerLight.position.copy(player.position).add(new T.Vector3(0,2.7,0));}
function updateEffects(dt){
 for(let i=effects.length-1;i>=0;i--){const e=effects[i];e.time+=dt;const p=e.time/e.life;if(p>=1){removeObject(e.mesh);effects.splice(i,1);continue;}e.mesh.material.opacity=(1-p)*.85;if(e.type==='ring'){const r=T.MathUtils.lerp(e.from,e.to,1-(1-p)*(1-p));e.mesh.scale.setScalar(r);}if(e.type==='slash'){e.mesh.rotation.z=e.angle-.35+p*.9;e.mesh.scale.setScalar(.8+p*.3);}if(e.type==='sparks'){const data=e.mesh.geometry.attributes.position.array;for(let j=0;j<data.length;j+=6){const v=j/2;for(let axis=0;axis<3;axis++){data[j+axis]+=e.velocity[v+axis]*dt;data[j+3+axis]=data[j+axis]-e.velocity[v+axis]*.022;}e.velocity[v+1]-=dt*9;}e.mesh.geometry.attributes.position.needsUpdate=true;}if(e.type==='particles'){const data=e.mesh.geometry.attributes.position.array;for(let j=0;j<data.length;j+=3){data[j]+=e.velocity[j]*dt;data[j+1]+=e.velocity[j+1]*dt;data[j+2]+=e.velocity[j+2]*dt;e.velocity[j+1]-=dt*6;}e.mesh.geometry.attributes.position.needsUpdate=true;}}
 combatEffects.update(dt);spellLight.intensity=Math.max(0,spellLight.intensity-dt*160);}
function floatText(text,pos,kind=''){const element=document.createElement('div');element.className=`damage-number ${kind}`;element.textContent=text;$('float-layer').append(element);floaters.push({element,pos:new T.Vector3(pos.x,1.9,pos.z),time:0,life:kind==='small'?1.4:.85,offset:(Math.random()-.5)*20});}
function updateFloaters(dt){for(let i=floaters.length-1;i>=0;i--){const f=floaters[i];f.time+=dt;if(f.time>=f.life){f.element.remove();floaters.splice(i,1);continue;}const projected=f.pos.clone().project(camera);const x=(projected.x*.5+.5)*innerWidth,y=(-projected.y*.5+.5)*innerHeight;f.element.style.transform=`translate(${x+f.offset}px,${y-f.time*55}px) translate(-50%,-50%)`;f.element.style.opacity=String(Math.min(1,(f.life-f.time)*3));}}
let hudClass=null,portraitsRequested=false;
